// Module 9 evidence: installs one real appliance from a package generated by the dev stack, waits for
// its inventory and schema snapshot to arrive over the agent gateway, then captures the Database
// Explorer fleet page, the deployment's database page and a table's schema page, plus the appliance's
// own status page. Removes the appliance afterwards.
// Requires the dev API to listen on the host address (AGENT_GATEWAY_HOST=0.0.0.0). Usage: node scripts/screenshots-m9.mjs
import { spawnSync } from 'node:child_process';
import { mkdirSync, mkdtempSync, readFileSync, realpathSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { chromium } from '@playwright/test';

const base = process.env.BASE_URL ?? 'http://localhost:3210';
const outDir = fileURLToPath(new URL('../../../docs/reports/module-09/', import.meta.url));
const shots = `${outDir}screenshots/`;
mkdirSync(shots, { recursive: true });
const env = Object.fromEntries(readFileSync(new URL('../../api/.env', import.meta.url), 'utf8').split(/\r?\n/).filter((l) => /^[A-Z0-9_]+=/.test(l)).map((l) => [l.slice(0, l.indexOf('=')), l.slice(l.indexOf('=') + 1)]));
const sh = (cmd, timeout = 400_000) => {
  const r = spawnSync('wsl', ['--exec', 'bash', '-c', cmd], { encoding: 'utf8', timeout });
  return { code: r.status, out: (r.stdout ?? '').trim(), err: (r.stderr ?? '').trim() };
};
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const browser = await chromium.launch({ channel: 'msedge' });
const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 }, deviceScaleFactor: 2 });
const page = await ctx.newPage();
const login = await page.request.post(`${base}/api/v1/auth/login`, { data: { email: 'avery.admin@psacc.test', password: env.SEED_DEFAULT_PASSWORD }, headers: { origin: base } });
if (login.status() !== 200) throw new Error(`login ${login.status()}`);
const csrf = async () => ({ origin: base, 'x-csrf-token': (await ctx.cookies()).find((c) => c.name === 'psacc_csrf').value });
const api = async (method, path, data) => {
  const r = await page.request.fetch(`${base}/api/v1${path}`, { method, data, headers: await csrf() });
  if (!r.ok()) throw new Error(`${method} ${path} → ${r.status()} ${await r.text()}`);
  return (r.headers()['content-type'] ?? '').includes('json') ? r.json() : r.body();
};
const shot = async (p, name, full = true) => {
  await p.evaluate(() => window.scrollTo(0, 0));
  await p.addStyleTag({ content: 'nextjs-portal { display: none !important; }' }).catch(() => undefined);
  await p.waitForTimeout(400);
  await p.screenshot({ path: `${shots}${name}.png`, fullPage: full });
  console.log('saved', name);
};

const inst = (await api('GET', '/psa-instances?provider=autotask&status=active&pageSize=50')).items.find((i) => i.client.code !== 'CL-00001' && i.enabledServiceCount > 0);
const dep = await api('POST', '/deployments', { clientId: inst.client.id, psaInstanceId: inst.id, targetEnvironment: 'local_test', targetOs: 'linux', targetArch: 'amd64', hostLabel: 'module9-demo' });
const pkg = (await api('POST', `/deployments/${dep.id}/packages`, { tokenValidityHours: 4 })).currentPackage;
const zip = await api('POST', `/deployments/${dep.id}/packages/${pkg.id}/download`);
const winTmp = realpathSync.native(mkdtempSync(join(tmpdir(), 'psacc-m9-')));
writeFileSync(join(winTmp, pkg.fileName), zip);
const project = `psacc-${dep.code.toLowerCase()}`;
const work = `/tmp/psacc-m9shots/${project}`;
const port = 18000 + (Number(dep.code.replace(/\D/g, '')) % 1000);
const unixZip = sh(`wslpath -a '${join(winTmp, pkg.fileName)}'`).out;

try {
  await page.goto(`${base}/deployments/${dep.id}/database`, { waitUntil: 'networkidle' });
  await shot(page, '01-deployment-database-awaiting', false);
  let r = sh(`rm -rf /tmp/psacc-m9shots && mkdir -p /tmp/psacc-m9shots && cd /tmp/psacc-m9shots && unzip -q "${unixZip}" && cd ${project} && cp config/edge.env.template .env && scripts/install.sh`);
  if (r.code !== 0) throw new Error(`install failed: ${r.err || r.out}`);
  let d;
  for (let n = 0; n < 90; n++) {
    d = await api('GET', `/deployments/${dep.id}/database`);
    if (d.database && d.inspection.pendingTables === 0 && d.tables.length > 0) break;
    await sleep(2000);
  }
  if (!d.database || d.inspection.pendingTables !== 0) throw new Error(`schema details did not arrive: ${JSON.stringify(d.inspection)}`);

  await page.goto(`${base}/database-explorer`, { waitUntil: 'networkidle' });
  await shot(page, '02-explorer-fleet');
  await page.goto(`${base}/database-explorer?live=1`, { waitUntil: 'networkidle' });
  await shot(page, '03-explorer-live-only', false);
  await page.goto(`${base}/deployments/${dep.id}/database`, { waitUntil: 'networkidle' });
  await shot(page, '04-deployment-database');
  await page.goto(`${base}/deployments/${dep.id}/database/tables/public.helpdesk_tickets`, { waitUntil: 'networkidle' });
  await shot(page, '05-table-helpdesk-tickets');
  await page.goto(`${base}/deployments/${dep.id}/database/tables/public.ticket_events`, { waitUntil: 'networkidle' });
  await shot(page, '06-table-ticket-events', false);
  await page.setViewportSize({ width: 375, height: 812 });
  await page.goto(`${base}/deployments/${dep.id}/database`, { waitUntil: 'networkidle' });
  await shot(page, '07-deployment-database-mobile', false);
  await page.setViewportSize({ width: 1440, height: 900 });

  const t = await api('GET', `/deployments/${dep.id}/database/tables/public/helpdesk_tickets`);
  writeFileSync(`${outDir}table-detail-api-sample.json`, JSON.stringify({ ...t, deploymentId: '(omitted)', client: { ...t.client, id: '(omitted)' } }, null, 2));
  writeFileSync(`${outDir}database-api-sample.json`, JSON.stringify({ database: d.database, inspection: d.inspection, errors: d.errors, tables: d.tables.map((x) => ({ ...x })) }, null, 2));
  r = sh(`cd ${work} && docker compose -f compose.yaml logs --no-log-prefix edge-agent | grep -E 'enrolled|schema snapshot|reports delivered' | head -6`);
  writeFileSync(`${outDir}agent-log-excerpt.txt`, `$ docker compose logs edge-agent\n${r.out}\n`);
  // The inspector role on the real appliance: catalog only, no table privileges.
  const sql = "SELECT count(*) || ' of ' || (SELECT count(*) FROM pg_tables WHERE schemaname = 'public') || ' public tables readable by psa_edge_inspector' FROM pg_tables WHERE schemaname = 'public' AND has_table_privilege('psa_edge_inspector', (schemaname || '.' || tablename)::regclass, 'SELECT')";
  r = sh(`cd ${work} && docker compose -f compose.yaml exec -T edge-postgres sh -c 'PGPASSWORD="$(cat /run/secrets/postgres_owner_password)" psql -h 127.0.0.1 -U psa_edge_owner -d psa_edge -qtAX' <<'SQL'\n${sql}\nSQL`);
  writeFileSync(`${outDir}inspector-privileges.txt`, `$ psql (as the database owner, on the appliance)\n${sql}\n--\n${r.out || r.err}\n`);
} finally {
  sh(`cd ${work} && docker compose -f compose.yaml down --volumes --remove-orphans; rm -rf /tmp/psacc-m9shots`);
  rmSync(winTmp, { recursive: true, force: true });
  await browser.close();
}
